// "Schriften der Welt" world map: an inline SVG with the script regions coloured and one round,
// focusable pin per script. Data comes from worldMapData.ts (generated by tools/make-worldmap.py).
import './worldMap.css';
import { LAND, MAP_H, MAP_W, REGION_ANCHORS, REGION_PATHS, type MapRegion } from './worldMapData.ts';

const SVG_NS = 'http://www.w3.org/2000/svg';

export interface WorldMapPin {
  script: string;
  region: MapRegion;
  glyph: string;
  /** pin centre in viewBox px; a leader line runs to the region anchor when it is away from it */
  at: readonly [number, number];
}

export const REGION_COLORS: Record<MapRegion, string> = {
  latin: '#ffc75f',
  japan: '#ff6f91',
  kyrillisch: '#4fb3ff',
  arabisch: '#7ccf6b',
  devanagari: '#ff9671',
  griechisch: '#8f7bff',
  hebraeisch: '#ff6fd8',
  hangul: '#00c9b7',
  thai: '#c38bff',
};

const A = REGION_ANCHORS;
/** One pin per script. Positions are hand-placed so the crowded Europe / Middle East pins don't overlap. */
export const WORLD_MAP_PINS: readonly WorldMapPin[] = [
  { script: 'druck', region: 'latin', glyph: 'Aa', at: [A.latin[0] - 70, A.latin[1] - 34] },
  { script: 'grund', region: 'latin', glyph: 'Aa', at: [A.latin[0] - 70, A.latin[1] + 10] },
  { script: 'schreib', region: 'latin', glyph: 'Aa', at: [A.latin[0] - 70, A.latin[1] + 54] },
  { script: 'hiragana', region: 'japan', glyph: 'あ', at: [A.japan[0] + 32, A.japan[1] - 22] },
  { script: 'katakana', region: 'japan', glyph: 'ア', at: [A.japan[0] + 32, A.japan[1] + 22] },
  { script: 'kyrillisch', region: 'kyrillisch', glyph: 'Б', at: [A.kyrillisch[0], A.kyrillisch[1]] },
  { script: 'arabisch', region: 'arabisch', glyph: 'ب', at: [A.arabisch[0], A.arabisch[1]] },
  { script: 'devanagari', region: 'devanagari', glyph: 'क', at: [A.devanagari[0], A.devanagari[1]] },
  { script: 'griechisch', region: 'griechisch', glyph: 'Ω', at: [A.griechisch[0] - 8, A.griechisch[1] + 24] },
  { script: 'hebraeisch', region: 'hebraeisch', glyph: 'א', at: [A.hebraeisch[0] + 22, A.hebraeisch[1] - 24] },
  { script: 'hangul', region: 'hangul', glyph: '한', at: [A.hangul[0] - 22, A.hangul[1] - 12] },
  { script: 'thai', region: 'thai', glyph: 'ก', at: [A.thai[0], A.thai[1]] },
];

const PIN_R = 19;

function el<K extends keyof SVGElementTagNameMap>(tag: K, attrs: Record<string, string | number> = {}): SVGElementTagNameMap[K] {
  const e = document.createElementNS(SVG_NS, tag);
  for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, String(v));
  return e;
}

/** Region a script belongs to, or undefined. */
export function regionOfScript(script: string): MapRegion | undefined {
  return WORLD_MAP_PINS.find((p) => p.script === script)?.region;
}

/** Scripts of a region, in pin order. */
export function scriptsOfRegion(region: MapRegion): string[] {
  return WORLD_MAP_PINS.filter((p) => p.region === region).map((p) => p.script);
}

/**
 * Renders the map. Pins call `onPick(script)`. Tapping a region's land calls `onPick(script)` for
 * single-script regions; for regions with several scripts ('latin', 'japan') it calls
 * `onPick(region)` unless the selected script already belongs to that region (then nothing happens).
 */
export function renderWorldMap(opts: {
  selected: string;
  onPick: (regionOrScript: string) => void;
  labels: Record<string, string>;
}): SVGSVGElement {
  const svg = el('svg', {
    class: 'world-map',
    viewBox: `0 0 ${MAP_W} ${MAP_H}`,
    width: '100%',
    preserveAspectRatio: 'xMidYMid meet',
    role: 'group',
  });
  if (opts.labels.worldMap) svg.setAttribute('aria-label', opts.labels.worldMap);

  svg.append(el('rect', { class: 'wm-ocean', x: 0, y: 0, width: MAP_W, height: MAP_H, rx: 28 }));
  svg.append(el('path', { class: 'wm-land', d: LAND, 'aria-hidden': 'true' }));

  const regions = el('g', { class: 'wm-regions', 'aria-hidden': 'true' });
  for (const region of Object.keys(REGION_PATHS) as MapRegion[]) {
    const p = el('path', { class: `wm-region wm-r-${region}`, d: REGION_PATHS[region], fill: REGION_COLORS[region] });
    p.dataset.region = region;
    p.addEventListener('click', () => {
      const scripts = scriptsOfRegion(region);
      if (scripts.length === 1) opts.onPick(scripts[0]);
      else if (!scripts.includes(svg.dataset.selected ?? '')) opts.onPick(region);
    });
    regions.append(p);
  }
  svg.append(regions);

  const lines = el('g', { class: 'wm-leaders', 'aria-hidden': 'true' });
  const pins = el('g', { class: 'wm-pins' });
  for (const pin of WORLD_MAP_PINS) {
    const [ax, ay] = REGION_ANCHORS[pin.region];
    const [x, y] = pin.at;
    if (Math.hypot(x - ax, y - ay) > PIN_R) {
      lines.append(el('line', { class: `wm-leader wm-leader-${pin.script}`, x1: ax, y1: ay, x2: x, y2: y }));
      lines.append(el('circle', { class: 'wm-leader-dot', cx: ax, cy: ay, r: 3.5 }));
    }
    const g = el('g', {
      class: `wm-pin pin-${pin.script}`,
      transform: `translate(${x} ${y})`,
      role: 'button',
      tabindex: 0,
      'aria-label': opts.labels[pin.script] ?? pin.script,
    });
    g.dataset.script = pin.script;
    const title = el('title');
    title.textContent = opts.labels[pin.script] ?? pin.script;
    g.append(title);
    g.append(el('circle', { class: 'wm-pin-bg', r: PIN_R, stroke: REGION_COLORS[pin.region] }));
    const t = el('text', { class: 'wm-glyph', 'text-anchor': 'middle', 'dominant-baseline': 'central', y: 1 });
    t.textContent = pin.glyph;
    g.append(t);
    g.addEventListener('click', () => opts.onPick(pin.script));
    g.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        opts.onPick(pin.script);
      }
    });
    pins.append(g);
  }
  svg.append(lines, pins);

  setWorldMapSelected(svg, opts.selected);
  return svg;
}

/** Moves the highlight to another script without re-rendering. */
export function setWorldMapSelected(svg: SVGSVGElement, script: string): void {
  svg.dataset.selected = script;
  const region = regionOfScript(script);
  for (const p of svg.querySelectorAll<SVGPathElement>('.wm-region')) p.classList.toggle('is-selected', p.dataset.region === region);
  for (const g of svg.querySelectorAll<SVGGElement>('.wm-pin')) {
    const on = g.dataset.script === script;
    g.classList.toggle('is-selected', on);
    g.setAttribute('aria-pressed', String(on));
  }
  // draw the selected region last so its thick outline is not covered by neighbours
  const sel = svg.querySelector('.wm-region.is-selected');
  sel?.parentNode?.append(sel);
}
